USE biblioteca;

CREATE TABLE IF NOT EXISTS Publishers (PublisherId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(150) NOT NULL, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Publishers_Name UNIQUE (Name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS Genres (GenreId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, Name VARCHAR(100) NOT NULL, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT UQ_Genres_Name UNIQUE (Name)) ENGINE=InnoDB;

INSERT INTO Publishers (Name) VALUES ('Prentice Hall'), ('Companhia das Letras') ON DUPLICATE KEY UPDATE Name=VALUES(Name);
INSERT INTO Genres (Name) VALUES ('Programação'), ('Romance') ON DUPLICATE KEY UPDATE Name=VALUES(Name);

ALTER TABLE Books ADD COLUMN PublisherId BIGINT UNSIGNED NULL;
UPDATE Books SET PublisherId = (SELECT PublisherId FROM Publishers WHERE Name = CASE WHEN Title = 'Clean Code' THEN 'Prentice Hall' ELSE 'Companhia das Letras' END) WHERE PublisherId IS NULL;
ALTER TABLE Books MODIFY COLUMN PublisherId BIGINT UNSIGNED NOT NULL;
ALTER TABLE Books ADD CONSTRAINT FK_Books_Publishers FOREIGN KEY (PublisherId) REFERENCES Publishers(PublisherId);

CREATE TABLE IF NOT EXISTS BookGenres (BookId BIGINT UNSIGNED NOT NULL, GenreId BIGINT UNSIGNED NOT NULL, PRIMARY KEY (BookId, GenreId), CONSTRAINT FK_BookGenres_Books FOREIGN KEY (BookId) REFERENCES Books(BookId), CONSTRAINT FK_BookGenres_Genres FOREIGN KEY (GenreId) REFERENCES Genres(GenreId)) ENGINE=InnoDB;
INSERT IGNORE INTO BookGenres SELECT b.BookId,g.GenreId FROM Books b JOIN Genres g ON (b.Title='Clean Code' AND g.Name='Programação') OR (b.Title='Dom Casmurro' AND g.Name='Romance');

CREATE TABLE IF NOT EXISTS Reservations (ReservationId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, BookId BIGINT UNSIGNED NOT NULL, ReaderId BIGINT UNSIGNED NOT NULL, ReservedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, Status ENUM('ACTIVE','FULFILLED','CANCELLED') NOT NULL DEFAULT 'ACTIVE', CONSTRAINT FK_Reservations_Books FOREIGN KEY (BookId) REFERENCES Books(BookId), CONSTRAINT FK_Reservations_Readers FOREIGN KEY (ReaderId) REFERENCES Readers(ReaderId), INDEX IX_Reservations_Book_Status (BookId, Status), INDEX IX_Reservations_Reader_Status (ReaderId, Status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS Fines (FineId BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, LoanId BIGINT UNSIGNED NOT NULL, Amount DECIMAL(10,2) NOT NULL, Reason VARCHAR(200) NOT NULL, CreatedAt DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PaidAt DATETIME NULL, CONSTRAINT UQ_Fines_Loan UNIQUE (LoanId), CONSTRAINT FK_Fines_Loans FOREIGN KEY (LoanId) REFERENCES Loans(LoanId)) ENGINE=InnoDB;
